"""Writes examples/cache_lab/*.s (the WP-06 cache benchmarks).

Every program: no .data, no pseudo-instructions, no input, ends by running off the end.
Arrays live at 0x10000 (lui x5, 0x10). Each register write is followed by PAD nops so the
no-hazard-unit pipeline (nh-nf) computes the same addresses as the others.
usage: gen_bench.py <out-dir>
"""
import os
import sys

PAD = 2
NOP = "addi x0, x0, 0"
WRITERS = {"lui", "addi", "add", "sub", "slli", "mul", "lw"}

HEADER = """# Atlas cache lab: {title}
# Generated by gen_bench.py (E8). Deterministic, no input; ends by running off the end.
# {what}
# 'addi x0, x0, 0' lines are padding: the nh-nf pipeline has no hazard unit, so every
# register write is followed by {pad} nops and all five models compute the same addresses.
"""


def pad(lines):
    out = []
    for ln in lines:
        out.append(ln)
        body = ln.split("#")[0].strip()
        if ":" in body:
            body = body.split(":", 1)[1].strip()
        if not body:
            continue
        op, _, rest = body.partition(" ")
        rd = rest.split(",")[0].strip()
        if op in WRITERS and rd != "x0":
            out.extend(["    " + NOP] * PAD)
    return out


def sweep(stride_words, array_words=1024, repeats=1):
    end_hi = (0x10000 + array_words * 4)
    assert end_hi % 4096 == 0 or array_words * 4 < 2048
    lines = ["    lui x5, 0x10             # x5 = array base 0x10000"]
    if array_words * 4 >= 2048:
        lines.append(f"    lui x7, {hex(end_hi >> 12)}            # x7 = end = base + {array_words * 4}")
    else:
        lines.append(f"    addi x7, x5, {array_words * 4}         # x7 = end = base + {array_words * 4}")
    lines += [f"    addi x10, x0, {repeats}           # x10 = sweeps left",
              "outer:",
              "    addi x6, x5, 0           # x6 = pointer",
              "loop:",
              "    lw x9, 0(x6)             # the measured access",
              "    add x8, x8, x6           # x8 = checksum of the addresses read",
              f"    addi x6, x6, {stride_words * 4}          # stride {stride_words} word(s)",
              "    blt x6, x7, loop",
              "    addi x10, x10, -1",
              "    bne x10, x0, outer"]
    return pad(lines)


def matmul(order):
    # A at 0x10000, B at 0x10100, C at 0x10200: 8x8 words each, row-major.
    lines = ["    lui x5, 0x10             # x5 = A = 0x10000",
             "    addi x21, x5, 256        # x21 = B = 0x10100",
             "    addi x22, x5, 512        # x22 = C = 0x10200",
             "    addi x20, x0, 8          # x20 = N",
             "    addi x23, x0, 64         # x23 = N*N",
             "    addi x13, x0, 0          # init: A[k] = k+1, B[k] = 2k+1",
             "init:",
             "    slli x18, x13, 2",
             "    add x19, x18, x5",
             "    addi x24, x13, 1",
             "    sw x24, 0(x19)",
             "    add x19, x18, x21",
             "    add x24, x24, x13",
             "    sw x24, 0(x19)",
             "    addi x13, x13, 1",
             "    blt x13, x23, init"]
    outer, mid = ("x11", "x12") if order == "ijk" else ("x12", "x11")
    lines += [f"    addi {outer}, x0, 0          # {'i' if outer == 'x11' else 'j'} (outer)",
              "L1:",
              f"    addi {mid}, x0, 0          # {'j' if mid == 'x12' else 'i'} (middle)",
              "L2:",
              "    addi x15, x0, 0          # sum = 0",
              "    slli x16, x11, 5",
              "    add x16, x16, x5         # x16 = &A[i][0]",
              "    slli x17, x12, 2",
              "    add x17, x17, x21        # x17 = &B[0][j]",
              "    addi x13, x0, 0          # k",
              "L3:",
              "    lw x18, 0(x16)           # A[i][k]",
              "    lw x19, 0(x17)           # B[k][j]",
              "    mul x18, x18, x19",
              "    add x15, x15, x18",
              "    addi x16, x16, 4         # next column of A",
              "    addi x17, x17, 32        # next row of B",
              "    addi x13, x13, 1",
              "    blt x13, x20, L3",
              "    slli x18, x11, 5",
              "    slli x19, x12, 2",
              "    add x18, x18, x19",
              "    add x18, x18, x22        # x18 = &C[i][j]",
              "    sw x15, 0(x18)           # C[i][j] = sum",
              "    add x8, x8, x15          # x8 = checksum",
              f"    addi {mid}, {mid}, 1",
              f"    blt {mid}, x20, L2",
              f"    addi {outer}, {outer}, 1",
              f"    blt {outer}, x20, L1"]
    return pad(lines)


def benchmarks():
    b = {}
    for s in (1, 2, 4, 8, 16, 32):
        b[f"stride_{s}"] = (f"stride {s}", f"One load sweep over a 1024-word array at stride {s} word(s): spatial locality.", sweep(s))
    b["temporal_repeat"] = ("temporal locality", "A 64-word (256-byte) array swept 4 times at stride 1: reuse after the first sweep.", sweep(1, 64, 4))
    b["matmul_ijk"] = ("8x8 matrix multiply, i-j-k", "C = A x B, 8x8 words, row-major; inner loop walks a row of A and a column of B.", matmul("ijk"))
    b["matmul_jik"] = ("8x8 matrix multiply, j-i-k", "Same as matmul_ijk with the two outer loops swapped.", matmul("jik"))
    return b


def main():
    out = sys.argv[1]
    os.makedirs(out, exist_ok=True)
    for name, (title, what, lines) in benchmarks().items():
        with open(os.path.join(out, name + ".s"), "w") as f:
            f.write(HEADER.format(title=title, what=what, pad=PAD))
            f.write("\n".join(lines) + "\n")


if __name__ == "__main__":
    main()
